from datetime import datetime
from typing import Dict, Optional


class Appointment:
    def __init__(
        self,
        appointment_id: int,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
    ) -> None:
        self.id = appointment_id
        self.patient = patient
        self.doctor = doctor
        self.start = start
        self.end = end


class Scheduler:
    def __init__(self) -> None:
        self._next_id: int = 1
        self._appointments: Dict[int, Appointment] = {}

    def book(
        self,
        patient: str,
        doctor: str,
        start: datetime,
        end: datetime,
        now: datetime,
    ) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start >= end:
            raise ValueError("Appointment start time must be before end time.")

        # Requirement 4: Booking an appointment that starts before `now` raises ValueError.
        if start < now:
            raise ValueError("Cannot book an appointment in the past.")

        # Requirement 3: A patient can have at most one upcoming appointment;
        # booking another one while the first is still upcoming raises ValueError.
        # An appointment is "upcoming" if its start time is in the future relative to `now`.
        for appt in self._appointments.values():
            if appt.patient == patient and appt.start >= now:
                raise ValueError(
                    f"Patient '{patient}' already has an upcoming appointment."
                )

        # Requirement 2: Booking an appointment that overlaps another appointment
        # of the same doctor raises ValueError.
        if not self.is_free(doctor, start, end):
            raise ValueError(
                f"Doctor '{doctor}' is not available during the requested time."
            )

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = Appointment(
            appt_id, patient, doctor, start, end
        )
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self._appointments:
            raise ValueError(f"Appointment ID {appointment_id} does not exist.")

        appt = self._appointments[appointment_id]
        if appt.start < now:
            raise ValueError("Cannot cancel an appointment that has already started.")

        del self._appointments[appointment_id]

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        if start >= end:
            raise ValueError("Start time must be before end time.")

        # Requirement 1: Appointments that only touch (one ends exactly when
        # the other starts) do not overlap.
        for appt in self._appointments.values():
            if appt.doctor == doctor:
                # Overlap condition: max(start1, start2) < min(end1, end2)
                if max(start, appt.start) < min(end, appt.end):
                    return False

        return True
```

